function doPost(e) {
  const props = PropertiesService.getScriptProperties();
  const body = JSON.parse((e.postData && e.postData.contents) || '{}');
  if (!props.getProperty('VOTE_SECRET') || body.secret !== props.getProperty('VOTE_SECRET')) {
    return json_({ ok: false, error: 'unauthorized' });
  }
  const lock = LockService.getScriptLock();
  lock.waitLock(10000); // throws if not acquired within 10 s
  try {
    const sheet = SpreadsheetApp.openById(props.getProperty('SHEET_ID')).getSheetByName('Votes');
    const ids = sheet.getRange(2, 5, Math.max(sheet.getLastRow() - 1, 1), 1).getValues().flat();
    if (ids.indexOf(body.voteId) === -1) {
      sheet.appendRow([new Date(), body.rugId, body.visitorId, body.vote, body.voteId]);
    }
    return json_({ ok: true, voteId: body.voteId });
  } finally {
    lock.releaseLock();
  }
}

