const EXEC_URL = process.env.APPS_SCRIPT_EXEC_URL!;   // https://script.google.com/macros/s/<deploymentId>/exec - server-only, never shipped to the client
const SECRET = process.env.VOTE_SECRET!;

export async function appendVote(v: { rugId: string; visitorId: string; vote: 'like' | 'dislike'; voteId: string }) {
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const res = await fetch(EXEC_URL, {
        method: 'POST',
        redirect: 'follow',                       // /exec answers 302 -> script.googleusercontent.com; Fetch re-issues it as GET
        headers: { 'content-type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ secret: SECRET, ...v }),
        signal: AbortSignal.timeout(10_000),
      });
      const data = (await res.json()) as { ok: boolean; error?: string };
      if (data.ok) return data;
      if (data.error === 'unauthorized') throw new Error('apps-script: unauthorized');
    } catch (err) {
      if (attempt === 1) throw err;
    }
  }
}

import { GoogleAuth } from 'google-auth-library';

const auth = new GoogleAuth({ scopes: ['https://www.googleapis.com/auth/drive.readonly'] });
const client = await auth.getClient();
const { token } = await client.getAccessToken();

const res = await fetch(EXEC_URL, {
  method: 'POST',
  redirect: 'follow',
  headers: { authorization: `Bearer ${token}`, 'content-type': 'text/plain;charset=utf-8' },
  body: JSON.stringify({ secret: SECRET, rugId, visitorId, vote, voteId }),
  signal: AbortSignal.timeout(10_000),
});
